/// <summary>
/// MPJ_24248 Price Data Extract
/// </summary>
[ExtensionOf(tableStr(EcoResValue))]
internal final class METEcoResValueTable_Extension
{
}

Method.Source:
/// <summary>
/// Table Update
/// </summary>
public void update()
{
    next update();
    
    if(GUPParameters::find().METPriceChangeTrackingEnable)
    {
        this.metTrackChange();
    }
}

    /// <summary>
    /// track changes
    /// </summary>
    public void metTrackChange()
    {
        CustTable                   custTable;
        CustomerInstanceValue       customerInstanceValue;
        
        InventTable                 inventTable;
        EcoResProductInstanceValue  ecoResProductInstanceValue;
        
        EcoResAttributeValue        ecoResAttributeValue;
        GUPEcoResAttributeParameter gupEcoResAttributeParameter;

        //Product attribute changes
        while select firstonly inventTable
            
            exists join    ecoResProductInstanceValue
            where   ecoResProductInstanceValue.Product  == InventTable.Product

            exists join    ecoResAttributeValue
            where   ecoResAttributeValue.InstanceValue  == ecoResProductInstanceValue.RecId
            &&      ecoResAttributeValue.Value          == this.recid

            exists join	gupEcoResAttributeParameter
            where	gupEcoResAttributeParameter.attribute                   == ecoResAttributeValue.attribute
            &&      gupEcoResAttributeParameter.IsEnabledAsPricingAttribute == NoYes::Yes

        {
            METPriceChangeEventProduct::metProcessTrackChange(inventTable);
        }

        //Customer attribute changes
        while select firstonly custTable
            
            exists join    customerInstanceValue
            where   customerInstanceValue.AccountNum         == custTable.AccountNum
            &&      customerInstanceValue.CustomerDataAreaId == curExt()
            
            exists join    ecoResAttributeValue
            where   ecoResAttributeValue.InstanceValue  == customerInstanceValue.RecId
            &&      ecoResAttributeValue.Value          == this.recid

            exists join	gupEcoResAttributeParameter
            where	gupEcoResAttributeParameter.attribute                   == ecoResAttributeValue.attribute
            &&      gupEcoResAttributeParameter.IsEnabledAsPricingAttribute == NoYes::Yes

        {
            METPriceChangeEventCustomer::metProcessTrackChange(custTable);
        }
    }
